const hasConfigureExternalAccessTask = `-- name: HasConfigureExternalAccessTask :one
SELECT EXISTS (
    SELECT 1 FROM task
    WHERE build_id = $1
      AND kind = 'configure_external_access'
      AND payload->>'team' = $2::text
      AND payload->>'fingerprint' = $3::text
) AS present
`

type HasConfigureExternalAccessTaskParams struct {
	BuildID     pgtype.UUID `json:"build_id"`
	Team        string      `json:"team"`
	Fingerprint string      `json:"fingerprint"`
}

// Dedup for the external-access reconciler, exactly like network access above:
// one configure_external_access task per (team, public-ports fingerprint), across
// all statuses. A content change to a team's `public:` ports yields a new
// fingerprint and a fresh task; an unchanged set never re-runs (the builder call
// is idempotent).
func (q *Queries) HasConfigureExternalAccessTask(ctx context.Context, arg HasConfigureExternalAccessTaskParams) (bool, error) {
	row := q.db.QueryRow(ctx, hasConfigureExternalAccessTask, arg.BuildID, arg.Team, arg.Fingerprint)
	var present bool
	err := row.Scan(&present)
	return present, err
}

const hasConfigureNetworkAccessTask = `-- name: HasConfigureNetworkAccessTask :one
SELECT EXISTS (
    SELECT 1 FROM task
    WHERE build_id = $1
      AND kind = 'configure_network_access'
      AND payload->>'team' = $2::text
      AND payload->>'fingerprint' = $3::text
) AS present
`

type HasConfigureNetworkAccessTaskParams struct {
	BuildID     pgtype.UUID `json:"build_id"`
	Team        string      `json:"team"`
	Fingerprint string      `json:"fingerprint"`
}

// Dedup for the network-access reconciler: exactly one configure_network_access
// task per (team, desired-config fingerprint), across ALL statuses. The
// fingerprint (a hash of the team's networks' names/CIDRs/visible_from) rides in
// the payload, so a content change yields a new fingerprint and a fresh task,
// while an unchanged config never re-runs regardless of the earlier task's
// outcome -- the builder call is idempotent, so re-asserting adds no value.
func (q *Queries) HasConfigureNetworkAccessTask(ctx context.Context, arg HasConfigureNetworkAccessTaskParams) (bool, error) {
	row := q.db.QueryRow(ctx, hasConfigureNetworkAccessTask, arg.BuildID, arg.Team, arg.Fingerprint)
	var present bool
	err := row.Scan(&present)
	return present, err
}

const hasOpenTeamAccessTask = `-- name: HasOpenTeamAccessTask :one
SELECT EXISTS (
    SELECT 1 FROM task
    WHERE build_id = $1
      AND kind IN ('open_access', 'close_access')
      AND status IN ('pending', 'leased')
      AND payload->>'team' = $2::text
) AS present
`

type HasOpenTeamAccessTaskParams struct {
	BuildID pgtype.UUID `json:"build_id"`
	Team    string      `json:"team"`
}

// Dedup for the access reconciler: team-level access tasks carry no
// deployed_object_id, so the partial unique index that dedups deploy/destroy
// tasks (CreateTaskIfNoneOpen) does not apply to them. Before enqueuing an
// open/close for a team, the reconciler checks there isn't already one pending
// or leased for that same team (matched by the team number in the payload), so
// a slow builder call doesn't get a fresh duplicate every pass.
func (q *Queries) HasOpenTeamAccessTask(ctx context.Context, arg HasOpenTeamAccessTaskParams) (bool, error) {
	row := q.db.QueryRow(ctx, hasOpenTeamAccessTask, arg.BuildID, arg.Team)
	var present bool
	err := row.Scan(&present)
	return present, err
}

const heartbeatTask = `-- name: HeartbeatTask :execrows
UPDATE task SET lease_expires_at = now() + $3::interval, updated_at = now()
WHERE id = $1 AND lease_owner = $2 AND status = 'leased'
`

type HeartbeatTaskParams struct {
	ID         pgtype.UUID     `json:"id"`
	LeaseOwner *string         `json:"lease_owner"`
	Column3    pgtype.Interval `json:"column_3"`
}

// Zero rows affected means the lease was already reclaimed out from under
// the caller (it should stop working immediately -- see internal/runner).
func (q *Queries) HeartbeatTask(ctx context.Context, arg HeartbeatTaskParams) (int64, error) {
	result, err := q.db.Exec(ctx, heartbeatTask, arg.ID, arg.LeaseOwner, arg.Column3)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

